# Prompt summary: Map-style dataset where each item is one whole zarr chunk; batches are built from several
# random chunks via collate, and Lightning's DistributedSampler handles DDP sharding/shuffling.
import torch
import xarray as xr
import zarr
import pandas as pd
from torch.utils.data import Dataset

from src.data_builders.data_utils import build_indices


def _read_time_index(path):
    idx = xr.open_zarr(path, consolidated=False).indexes["time"]
    if not isinstance(idx, pd.DatetimeIndex):          # cftime calendars -> pandas
        idx = idx.to_datetimeindex()
    return idx


class ChunkDataset(Dataset):
    def __init__(self, predictors_path:str, targets_path:str, static_features_path:str, blocks: list[tuple[str, str]] | None = None):

        if blocks is None:
            print("Warning: No blocks provided, ignoring split.")
            blocks = [(None, None)]

        self.pred_path, self.targ_path = predictors_path, targets_path
        p = zarr.open_group(self.pred_path, mode="r")["data"]
        self.chunk_t = p.chunks[0]
        n_full = p.shape[0] // self.chunk_t

        # Timesteps in this split, from the store's own time coordinate
        time = _read_time_index(self.pred_path)
        in_split = torch.zeros(len(time), dtype=bool)
        in_split[build_indices(time, blocks)] = True

        # Keep chunks that lie entirely inside the split
        per_chunk = in_split[: n_full * self.chunk_t].reshape(n_full, self.chunk_t)
        self.chunk_ids = torch.nonzero(per_chunk.all(axis=1)).squeeze(1)
        dropped = int(per_chunk.any(axis=1).sum() - len(self.chunk_ids))
        print(f"ChunkDataset: {len(self.chunk_ids)} chunks "
              f"({len(self.chunk_ids) * self.chunk_t} samples), "
              f"{dropped} boundary chunks dropped")

        self.target_variables = zarr.open_group(self.targ_path, mode="r")["channel"][:].tolist()
        self._pred = self._targ = None

        z_static = zarr.open_group(static_features_path, mode="r")
        self.static_features = torch.stack(
            [torch.from_numpy(z_static[v][:]).float() for v in ("orog", "sftlf")]
        )

    def __len__(self):
        return len(self.chunk_ids)

    def __getitem__(self, i):
        if self._pred is None:
            self._pred = zarr.open_group(self.pred_path, mode="r")["data"]
            self._targ = zarr.open_group(self.targ_path, mode="r")["data"]
        c = int(self.chunk_ids[i])                         # dataset position -> zarr chunk number
        sl = slice(c * self.chunk_t, (c + 1) * self.chunk_t)
        return torch.from_numpy(self._pred[sl]), torch.from_numpy(self._targ[sl])

    def collate(self, items):
        x = torch.cat([it[0] for it in items]).float()
        y_raw = torch.cat([it[1] for it in items]).float()
        y = {v: y_raw[:, j] for j, v in enumerate(self.target_variables)}
        return x, y